package cn.privatereader

import org.junit.Test
import org.junit.Assert.*
import java.nio.file.Files

class ReferenceBindingsTest {
 private fun resource(name:String="valid-v2.json")=parseReference(name,javaClass.getResourceAsStream("/reference-import/$name")!!.use{it.readBytes()})
 private fun withStore(block:(Store)->Unit){val root=Files.createTempDirectory("reference-bindings").toFile();try{block(Store(root))}finally{root.deleteRecursively()}}
 @Test fun previewHasNoWritesAndCommitPreservesSameNameCopies(){withStore{s->val b=s.importBook("合成.txt","正文".toByteArray());val a=resource();assertTrue(s.load(b.id)!!.resources.isEmpty());assertTrue(s.revisions(b.id).isEmpty());val first=s.importReference(b.id,b.workspaceId,b.chapters[0].scene.id,a);val second=s.importReference(b.id,b.workspaceId,b.chapters[0].scene.id,resource());assertEquals(2,second.resources.size);assertEquals(first.resources[0].title,second.resources[1].title);assertNotEquals(first.resources[0].id,second.resources[1].id);assertEquals(2,second.bindings.size);assertThrows(IllegalArgumentException::class.java){s.importReference(b.id,b.workspaceId,b.chapters[0].scene.id,a)};assertEquals(second,s.load(b.id))}}
 @Test fun staleWorkspaceAndUnknownSceneNeverCommit(){withStore{s->val b=s.importBook("合成.txt","正文".toByteArray());val a=resource();assertThrows(IllegalArgumentException::class.java){s.importReference(b.id,newId(),b.chapters[0].scene.id,a)};assertThrows(IllegalArgumentException::class.java){s.importReference(b.id,b.workspaceId,newId(),a)};assertEquals(b,s.load(b.id));assertTrue(s.revisions(b.id).isEmpty())}}
 @Test fun disabledFutureAndCrossWorkspacePartsNeverEnterContext(){withStore{s->val original=s.importBook("合成.txt","第一章 当前\n\n所选正文\n\n第二章 未来\n\n未来正文".toByteArray());val c=original.chapters.first();val b=s.importReference(original.id,original.workspaceId,c.scene.id,resource("valid-st-world.json"));val all=referenceContextParts(b,c.scene.id);assertEquals(1,all.size);val a=selectionAnchor(c,0,2);val empty=selectionRequest(b,c,a,"润色","轻");assertEquals("",empty.facts);val selected=selectionRequest(b,c,a,"润色","轻",referencePartIds=setOf(all[0].id));assertTrue(selected.facts.contains(all[0].content));val disabled=b.resources[0].entries.single{!it.enabled};assertThrows(IllegalArgumentException::class.java){selectionRequest(b,c,a,"润色","轻",referencePartIds=setOf("${b.resources[0].id}:entry:${disabled.id}"))};assertTrue(referenceContextParts(b,b.chapters[1].scene.id).isEmpty());assertTrue(referenceContextParts(b.copy(bindings=b.bindings.map{it.copy(enabled=false)}),c.scene.id).isEmpty());assertThrows(IllegalArgumentException::class.java){selectionRequest(b,c,a,"润色","轻",expectedWorkspaceId=newId())};val other=s.importBook("别的书.txt","另书".toByteArray());assertTrue(referenceContextParts(other,other.chapters[0].scene.id).isEmpty())}}
 @Test fun backupPreservesImmutableImportAndRestoresIndependentWorkspace(){withStore{s->val original=s.importBook("合成.txt","正文".toByteArray());val b=s.importReference(original.id,original.workspaceId,original.chapters[0].scene.id,resource());val card=StoryCard(kind=CardKind.CHARACTER,name=b.resources[0].title,notes=b.resources[0].characterText,sceneIds=listOf(b.chapters[0].scene.id),referenceId=b.resources[0].id);val saved=s.save(b.copy(cards=listOf(card)));val restored=s.importBackup(s.exportBackup(b.id));assertNotEquals(saved.workspaceId,restored.workspaceId);assertNotEquals(saved.id,restored.id);assertEquals(saved.resources,restored.resources);assertEquals(saved.bindings,restored.bindings);assertEquals(saved.cards,restored.cards);assertEquals(saved.resources[0].rawJson,restored.resources[0].rawJson);val edited=s.save(restored.copy(cards=restored.cards.map{it.copy(notes="独立编辑副本")}));assertEquals(saved.resources,edited.resources);assertEquals(saved,s.load(saved.id))}}
 @Test fun basicCharacterSelectionDoesNotIncludeExternalInstructionOrAuthorData(){withStore{s->val base=s.importBook("合成.txt","正文".toByteArray());val b=s.importReference(base.id,base.workspaceId,base.chapters[0].scene.id,resource());val part=referenceContextParts(b,b.chapters[0].scene.id).single{it.id.endsWith(":character")};val request=selectionRequest(b,b.chapters[0],selectionAnchor(b.chapters[0],0,2),"润色","轻",referencePartIds=setOf(part.id));assertTrue(request.facts.contains("摆渡人"));assertFalse(request.facts.contains("shell"));assertFalse(request.facts.contains("船要开了"));assertFalse(request.facts.contains("fixture"));assertFalse(request.facts.contains("system_prompt"))}}
 @Test fun invalidOrDuplicateBindingRejected(){withStore{s->val base=s.importBook("合成.txt","正文".toByteArray());val b=s.importReference(base.id,base.workspaceId,base.chapters[0].scene.id,resource());assertThrows(IllegalArgumentException::class.java){s.save(b.copy(bindings=b.bindings+b.bindings[0].copy(id=newId())))};assertThrows(IllegalArgumentException::class.java){s.save(b.copy(bindings=listOf(b.bindings[0].copy(sceneIds=listOf("absent")))))};assertThrows(IllegalArgumentException::class.java){s.save(b.copy(cards=listOf(StoryCard(kind=CardKind.CHARACTER,name="无效来源",referenceId=newId()))))};assertEquals(b,s.load(b.id))}}
 @Test fun malformedBackupReferenceFieldsRejectInsteadOfDefaulting(){withStore{s->
  val base=s.importBook("合成.txt","正文".toByteArray());val b=s.importReference(base.id,base.workspaceId,base.chapters[0].scene.id,resource());val backup=s.exportBackup(b.id)
  fun mutate(change:(org.json.JSONObject)->Unit):ByteArray {
   val entries=linkedMapOf<String,ByteArray>();java.util.zip.ZipInputStream(java.io.ByteArrayInputStream(backup)).use{z->while(true){val e=z.nextEntry?:break;entries[e.name]=z.readBytes()}}
   val book=org.json.JSONObject(String(entries.getValue("book.json"),Charsets.UTF_8));change(book);entries["book.json"]=book.toString().toByteArray()
   val manifest=org.json.JSONObject(String(entries.getValue("manifest.json"),Charsets.UTF_8));manifest.put("book.json",java.security.MessageDigest.getInstance("SHA-256").digest(entries.getValue("book.json")).joinToString(""){"%02x".format(it)});entries["manifest.json"]=manifest.toString().toByteArray()
   return java.io.ByteArrayOutputStream().also{out->java.util.zip.ZipOutputStream(out).use{z->entries.forEach{(name,data)->z.putNextEntry(java.util.zip.ZipEntry(name));z.write(data);z.closeEntry()}}}.toByteArray()
  }
  for(key in listOf("resources","bindings","workspaceId"))for(value in listOf(org.json.JSONObject.NULL,org.json.JSONObject(),42))assertTrue(runCatching{s.importBackup(mutate{it.put(key,value)})}.isFailure)
  for(key in listOf("enabled","pinnedRevision","sceneIds"))for(value in listOf(org.json.JSONObject.NULL,org.json.JSONObject(),"bad"))assertTrue(runCatching{s.importBackup(mutate{it.getJSONArray("bindings").getJSONObject(0).put(key,value)})}.isFailure)
  for(value in listOf(0,2,1.5,true))assertTrue(runCatching{s.importBackup(mutate{it.getJSONArray("bindings").getJSONObject(0).put("pinnedRevision",value)})}.isFailure)
  assertEquals(b,s.load(b.id));assertEquals(1,s.list().size)
 }}
}
